import React, { useState, useEffect } from 'react';
import { Heart, Plus, MapPin, Building2, Phone, AlertCircle, Loader2, X, Send } from 'lucide-react';
import { getBloodRequests, createBloodRequest } from '../services/requestService';

export default function FeedPage() {
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  const [formData, setFormData] = useState({
    patientName: '',
    bloodGroup: 'A+',
    hospitalName: '',
    district: 'ঢাকা',
    area: '',
    contactNumber: '',
    urgency: 'জরুরি',
    notes: ''
  });

  const bloodGroups = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'];
  const districts = ['ঢাকা', 'চট্টগ্রাম', 'রাজশাহী', 'সিলেট', 'খুলনা', 'বরিশাল', 'রংপুর', 'ময়মনসিংহ'];

  // লাইভ ডাটা লোড করা
  const fetchRequests = async () => {
    try {
      setLoading(true);
      const data = await getBloodRequests();
      setRequests(data);
    } catch (err) {
      console.error('রক্তের দাবী ফেচ করতে সমস্যা:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, []);

  // নতুন পোস্ট সাবমিট করা
  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    setError('');

    try {
      await createBloodRequest(formData);
      setShowModal(false);
      setFormData({
        patientName: '',
        bloodGroup: 'A+',
        hospitalName: '',
        district: 'ঢাকা',
        area: '',
        contactNumber: '',
        urgency: 'জরুরি',
        notes: ''
      });
      fetchRequests(); // পোস্ট আপডেট করা
    } catch (err) {
      setError('পোস্ট তৈরি করতে সমস্যা হয়েছে! তথ্যাদি আবার চেক করুন।');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto px-4 py-6 space-y-6">

      {/* Header Banner */}
      <div className="bg-gradient-to-r from-brand-600 to-rose-600 rounded-3xl p-6 text-white shadow-lg flex justify-between items-center">
        <div>
          <h1 className="text-xl font-black">লাইভ রক্তের দাবী ফিড</h1>
          <p className="text-xs opacity-90 font-medium mt-1">জরুরি রক্ত গ্রহীতাদের সাথে সরাসরি যোগাযোগ করুন</p>
        </div>
        <button
          onClick={() => setShowModal(true)}
          className="bg-white text-brand-600 hover:bg-rose-50 px-4 py-2.5 rounded-2xl font-bold text-xs shadow-md transition flex items-center gap-1.5 shrink-0"
        >
          <Plus className="w-4 h-4" /> পোস্ট করুন
        </button>
      </div>

      {/* Feed List */}
      {loading ? (
        <div className="flex justify-center items-center py-12">
          <Loader2 className="w-8 h-8 text-brand-600 animate-spin" />
        </div>
      ) : requests.length === 0 ? (
        <div className="bg-white rounded-3xl p-8 text-center border border-slate-100 shadow-sm space-y-2">
          <Heart className="w-10 h-10 text-slate-300 mx-auto" />
          <h3 className="text-sm font-bold text-slate-700">বর্তমানে কোনো রক্তের দাবী নেই</h3>
          <p className="text-xs text-slate-400">নতুন রিকুয়েস্ট থাকলে এখানে প্রদর্শিত হবে।</p>
        </div>
      ) : (
        <div className="space-y-4">
          {requests.map((req) => (
            <div key={req.id} className="bg-white rounded-3xl p-5 border border-slate-100 shadow-sm space-y-4 relative overflow-hidden">
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-2xl bg-rose-50 text-brand-600 font-black text-lg flex items-center justify-center border border-rose-100">
                    {req.bloodGroup}
                  </div>
                  <div>
                    <h2 className="text-sm font-black text-slate-900">{req.patientName}</h2>
                    <span className={`inline-block px-2 py-0.5 rounded-full text-[10px] font-bold mt-1 ${
                      req.urgency === 'জরুরি' ? 'bg-rose-100 text-rose-700' : 'bg-amber-100 text-amber-700'
                    }`}>
                      {req.urgency}
                    </span>
                  </div>
                </div>

                <a
                  href={`tel:${req.contactNumber}`}
                  className="bg-emerald-500 hover:bg-emerald-600 text-white px-3.5 py-2 rounded-xl text-xs font-bold transition flex items-center gap-1.5 shadow-sm"
                >
                  <Phone className="w-3.5 h-3.5" /> কল করুন
                </a>
              </div>

              <div className="grid grid-cols-2 gap-2 text-xs font-medium text-slate-600 bg-slate-50 p-3 rounded-2xl">
                <div className="flex items-center gap-1.5">
                  <Building2 className="w-3.5 h-3.5 text-slate-400 shrink-0" />
                  <span className="truncate">{req.hospitalName}</span>
                </div>
                <div className="flex items-center gap-1.5">
                  <MapPin className="w-3.5 h-3.5 text-slate-400 shrink-0" />
                  <span className="truncate">{req.area}, {req.district}</span>
                </div>
              </div>

              {req.notes && (
                <p className="text-xs text-slate-600 bg-amber-50/60 p-3 rounded-2xl border border-amber-100/60">
                  {req.notes}
                </p>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Modal for Creating Request */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-3xl p-6 border border-slate-100 shadow-2xl space-y-4 max-h-[90vh] overflow-y-auto">
            
            <div className="flex justify-between items-center border-b border-slate-100 pb-3">
              <h2 className="text-sm font-black text-slate-900">নতুন রক্তের দাবী জানান</h2>
              <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-5 h-5" />
              </button>
            </div>

            {error && (
              <div className="bg-rose-50 border border-rose-200 text-rose-700 text-xs font-bold p-3 rounded-xl flex items-center gap-2">
                <AlertCircle className="w-4 h-4 shrink-0" />
                <span>{error}</span>
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">রোগীর নাম</label>
                <input
                  type="text"
                  required
                  value={formData.patientName}
                  onChange={(e) => setFormData({ ...formData, patientName: e.target.value })}
                  placeholder="রোগীর নাম লিখুন"
                  className="w-full px-3.5 py-2 rounded-xl border border-slate-200 text-xs font-medium focus:outline-none focus:border-brand-600 bg-slate-50"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">রক্তের গ্রুপ</label>
                  <select
                    value={formData.bloodGroup}
                    onChange={(e) => setFormData({ ...formData, bloodGroup: e.target.value })}
                    className="w-full px-3 py-2 rounded-xl border border-slate-200 text-xs font-bold focus:outline-none focus:border-brand-600 bg-slate-50"
                  >
                    {bloodGroups.map((bg) => (
                      <option key={bg} value={bg}>{bg}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">জরুরিত্ব</label>
                  <select
                    value={formData.urgency}
                    onChange={(e) => setFormData({ ...formData, urgency: e.target.value })}
                    className="w-full px-3 py-2 rounded-xl border border-slate-200 text-xs font-bold focus:outline-none focus:border-brand-600 bg-slate-50"
                  >
                    <option value="জরুরি">জরুরি</option>
                    <option value="অতি জরুরি">অতি জরুরি</option>
                    <option value="সাধারণ">সাধারণ</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">হাসপাতাল / ঠিকানা</label>
                <input
                  type="text"
                  required
                  value={formData.hospitalName}
                  onChange={(e) => setFormData({ ...formData, hospitalName: e.target.value })}
                  placeholder="যেমন: ঢাকা মেডিকেল কলেজ হাসপাতাল"
                  className="w-full px-3.5 py-2 rounded-xl border border-slate-200 text-xs font-medium focus:outline-none focus:border-brand-600 bg-slate-50"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">জেলা</label>
                  <select
                    value={formData.district}
                    onChange={(e) => setFormData({ ...formData, district: e.target.value })}
                    className="w-full px-3 py-2 rounded-xl border border-slate-200 text-xs font-bold focus:outline-none focus:border-brand-600 bg-slate-50"
                  >
                    {districts.map((d) => (
                      <option key={d} value={d}>{d}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">এলাকা / থানা</label>
                  <input
                    type="text"
                    required
                    value={formData.area}
                    onChange={(e) => setFormData({ ...formData, area: e.target.value })}
                    placeholder="যেমন: ধানমন্ডি"
                    className="w-full px-3.5 py-2 rounded-xl border border-slate-200 text-xs font-medium focus:outline-none focus:border-brand-600 bg-slate-50"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">যোগাযোগের নম্বর</label>
                <input
                  type="tel"
                  required
                  value={formData.contactNumber}
                  onChange={(e) => setFormData({ ...formData, contactNumber: e.target.value })}
                  placeholder="01711XXXXXX"
                  className="w-full px-3.5 py-2 rounded-xl border border-slate-200 text-xs font-medium focus:outline-none focus:border-brand-600 bg-slate-50"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">অতিরিক্ত বিবরণ (ঐচ্ছিক)</label>
                <textarea
                  rows="2"
                  value={formData.notes}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  placeholder="যেমন: ২ ব্যাগ রক্ত লাগবে, সকাল ৯টার মধ্যে..."
                  className="w-full px-3.5 py-2 rounded-xl border border-slate-200 text-xs font-medium focus:outline-none focus:border-brand-600 bg-slate-50 resize-none"
                />
              </div>

              <button
                type="submit"
                disabled={submitting}
                className="w-full bg-brand-600 hover:bg-brand-700 text-white py-2.5 rounded-xl font-bold text-xs shadow-lg shadow-brand-600/30 transition flex items-center justify-center gap-2 disabled:opacity-50 mt-2"
              >
                {submitting ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <>
                    <Send className="w-4 h-4" /> পোস্ট সাবমিট করুন
                  </>
                )}
              </button>
            </form>

          </div>
        </div>
      )}

    </div>
  );
}
